import logging
import os
import time
import zipfile

from taf.fdsw.rc.clients.exceptions import TimeoutExceeded
from taf.fdsw.rc.interfaces.FDSW18SP.diagnostics import Diagnostics

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
logging.basicConfig(level=logging.INFO)


class Diagnostics19(Diagnostics):

    def download_technical_logs(self, zip_path, timeout):
        self._start_collecting(timeout)
        logger.info('Collecting log files ...')

        self._get_log_files(zip_path=zip_path, timeout=timeout)
        logger.info('Files collected')

    def _start_collecting(self, timeout):
        self._client.send(
            method='diagnostics.logs.startCollecting',
            timeout=timeout,
            parameters={'type': 'Full'})  # TODO: Remove param once removed from the API

    def _get_log_files(self, zip_path, timeout):
        operation_timeout = timeout + time.time()
        zip_obj = zipfile.ZipFile(zip_path, mode='w', compression=zipfile.ZIP_DEFLATED)

        while True:
            if time.time() > operation_timeout:
                raise TimeoutExceeded
            resp = self._get_file(30)
            if resp.data is None:
                break
            self._file_reciever(resp, zip_obj)
        zip_obj.close()

    def stop_collecting_logs(self, timeout):
        resp = self._client.send(
            method='diagnostics.logs.stopCollecting',
            timeout=timeout,
            parameters={})
        return resp.data

    def _get_file(self, timeout):
        resp = self._client.send(
            method='diagnostics.logs.downloadFile',
            timeout=timeout,
            parameters={}
        )
        return resp

    def _file_reciever(self, resp, zip_obj):
        file_name = os.path.basename(resp.data)
        content = resp.payload
        zip_obj.writestr(file_name, content)
